mapper.select:
SELECT id, username, full_name, email, region_abbreviation, phone_number, avatar_url, status, department_id, position_id, created_at, updated_at FROM "user"
ORDER BY
${order.property} ${order.direction}
LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT id, username, full_name, email, region_abbreviation, phone_number, avatar_url, status, department_id, position_id, created_at, updated_at FROM "user"
AND department_id IN (WITH RECURSIVE SubDepartments AS ( SELECT id FROM department WHERE id = #{wrapper.departmentId} UNION ALL SELECT d.id FROM department d INNER JOIN SubDepartments sd ON d.parent_id = sd.id) SELECT id FROM SubDepartments)
AND username LIKE '%' || #{wrapper.username} || '%'
AND region_abbreviation = #{wrapper.regionAbbreviation}
AND phone_number = #{wrapper.phoneNumber}
AND status = #{wrapper.status}::USER_STATUS
AND created_at >= #{wrapper.createdAtStart}
AND created_at <= #{wrapper.createdAtEnd}
ORDER BY
${order.property} ${order.direction}
LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT COUNT(*) FROM "user"
AND department_id IN (WITH RECURSIVE SubDepartments AS ( SELECT id FROM department WHERE id = #{wrapper.departmentId} UNION ALL SELECT d.id FROM department d INNER JOIN SubDepartments sd ON d.parent_id = sd.id) SELECT id FROM SubDepartments)
AND username LIKE '%' || #{wrapper.username} || '%'
AND region_abbreviation = #{wrapper.regionAbbreviation}
AND phone_number = #{wrapper.phoneNumber}
AND status = #{wrapper.status}::USER_STATUS
AND created_at >= #{wrapper.createdAtStart}
AND created_at <= #{wrapper.createdAtEnd}

SELECT u.id, u.username, u.full_name, u.email, u.region_abbreviation, u.phone_number, u.avatar_url, u.status, u.department_id, d.name AS department_name, u.position_id, p.name AS position_name, u.created_at, u.updated_at FROM "user" u LEFT JOIN department d ON u.department_id = d.id LEFT JOIN position p ON u.position_id = p.id
AND department_id IN (WITH RECURSIVE SubDepartments AS ( SELECT id FROM department WHERE id = #{wrapper.departmentId} UNION ALL SELECT d.id FROM department d INNER JOIN SubDepartments sd ON d.parent_id = sd.id) SELECT id FROM SubDepartments)
AND username LIKE '%' || #{wrapper.username} || '%'
AND region_abbreviation = #{wrapper.regionAbbreviation}
AND phone_number = #{wrapper.phoneNumber}
AND u.status = #{wrapper.status}::USER_STATUS
AND u.created_at >= #{wrapper.createdAtStart}
AND u.created_at <= #{wrapper.createdAtEnd}
ORDER BY
${order.property} ${order.direction}
LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}
